  createCrossmint,
  CrossmintWallets,
  EVMWallet,
  WalletNotAvailableError,
} = require("@crossmint/wallets-sdk");

const CHAIN = "base-sepolia";
const MESSAGE = "Hello from Crossmint";
const WALLET_LOCATOR = "userId:demo-user-001:evm-smart-wallet";
const OWNER = "userId:demo-user-001";
const RESULT_PATH = "/home/user/sign_result.json";

const baseLog = {
  chain: CHAIN,
  message: MESSAGE,
  signature: "mock-signature",
  wallet_type: "evm-smart-wallet",
};

async function writeLog(extra = {}) {
  const payload = { ...baseLog, ...extra };
  await fs.writeFile(RESULT_PATH, JSON.stringify(payload, null, 2));
}

async function main() {
  const apiKey = process.env.CROSSMINT_API_KEY;
  if (!apiKey) {
    throw new Error("Missing CROSSMINT_API_KEY environment variable");
  }

  const crossmint = createCrossmint({ apiKey });
  const wallets = CrossmintWallets.from(crossmint);

  let wallet;
  try {
    wallet = await wallets.getWallet(WALLET_LOCATOR, { chain: CHAIN });
  } catch (error) {
    if (!(error instanceof WalletNotAvailableError)) {
      throw error;
    }

    const recoverySecret = process.env.CROSSMINT_RECOVERY_SECRET;
    if (!recoverySecret) {
      throw new Error("Missing CROSSMINT_RECOVERY_SECRET for server recovery");
    }

    wallet = await wallets.createWallet({
      chain: CHAIN,
      owner: OWNER,
      recovery: {
        type: "server",
        secret: recoverySecret,
      },
    });
  }

  const evmWallet = EVMWallet.from(wallet);
  const signature = await evmWallet.signMessage({ message: MESSAGE });

  await writeLog({ signature });
}

